// RISHU.COM — Neon Redesign Build A — rishuFace.js
// Rishu's face = the user's own photo (decided 2026-11-17, "fight me bhi
// yahi same lagana no change"). The two crops below are EXACT crops of
// the original photo (~/workspace/user/media_library/image/
// WhatsApp_Image_2026-10-20_at_3.39.09_PM.jpeg) — no AI regeneration,
// no retouching: face, skin tone and mustache are exactly as photographed.
// Only the crop and the JPEG compression changed.
//
// Why base64 in code: the GitHub push route is UTF-8 text only, so a
// binary image file cannot be pushed that way. These two small JPEGs
// (~28 KB + ~21 KB) ride in this text file instead. Total ~65 KB of
// base64 — still smaller than one icon PNG.
//
// 4K sharpness (2026-11-17): both crops are 512 px — the practical ceiling
// for this 575x918 source photo (the face box is 480 px native, the
// portrait box 495 px, so 512 is a ~1.05x upscale, not empty magnification).
// Anything larger would add bytes without adding detail.
//
// RISHU_FACE_PORTRAIT — head + shoulders, 512x683. Used for the
// character-select card avatar and the HUD portrait (exact photo).
// RISHU_FACE_TEXTURE — tight face square, 512x512. Used for the 3D
// fighter's face cap (fighterModels.js); the cap fades its edges into
// Rishu's skin tone, which is sampled from the same photo (#715341).

export const RISHU_FACE_PORTRAIT = 'data:image/jpeg;base64,';
export const RISHU_FACE_TEXTURE = 'data:image/jpeg;base64,';
